    pattern: 'Final acute with long -α',
    explanation: 'The acute falls on the last syllable in both forms. Herodian gives this pair for the feminine in long -α corresponding to a masculine in -ος.'
  },
  {
    forms: ['φίλος', 'φίλη'],
    pattern: 'Penultimate acute with -η',
    explanation: 'Both forms have an acute on the next-to-last syllable. The feminine ends in -η.'
  },
  {
    forms: ['βαρύτερος', 'βαρυτέρα'],
    pattern: 'The acute moves',
    explanation: 'The masculine has an acute on the antepenult (third from last). In the feminine it moves to the penult (next to last). The accent is acute in both.'
  },
  {
    forms: ['ἀργυροῦς', 'ἀργυρᾶ'],
    pattern: 'Circumflex with long -α',
    explanation: 'The final syllable has a circumflex in both forms. This is the long -α example corresponding to circumflexed -οῦς.'
  },
  {
