}

function show(entry) {
  for (const example of entries) {
    example.button.setAttribute('aria-pressed', String(example === entry));
  }
  forms.hidden = !entry;
  forms.textContent = entry ? entry.forms.join(' → ') : '';
  if (entry) {
    pattern.textContent = entry.pattern;
    explanation.textContent = entry.explanation;
  } else if (input.value.trim()) {
    pattern.textContent = 'Form outside this selection';
    explanation.textContent = 'Choose a listed example or enter either Greek form in a listed pair.';
  } else {
    pattern.textContent = 'Choose a form';
    explanation.textContent = 'The entry shows where the accent falls and which ending Herodian discusses.';
  }
}

for (const entry of entries) {
  for (const form of entry.forms) lookup.set(key(form), entry);
  const example = document.createElement('button');
  const feminine = entry.forms.at(-1);
  example.type = 'button';
  example.lang = 'grc';
  example.textContent = feminine;
  example.setAttribute('aria-pressed', 'false');
  example.addEventListener('click', () => {
    input.value = feminine;
    show(entry);
  });
  entry.button = example;
  examples.append(example);
}

function lookUp() {
  show(lookup.get(key(input.value)));
}

