const input = document.querySelector('#inp');
const mode = document.querySelector('#mode');
const orthography = document.querySelector('#dial');
const fields = {
  norm: document.querySelector('#norm'),
  ending: document.querySelector('#ending'),
  target: document.querySelector('#target'),
  out: document.querySelector('#out'),
  why: document.querySelector('#why')
};

const antepenult = 'proparoxytone (antepenult)';
const ultima = 'oxytone (ultima)';
const lesson = new Map();
const diphthongs = new Set(['αι', 'ει', 'οι', 'υι', 'αυ', 'ευ', 'ηυ', 'ου', 'ωυ']);
const vowel = /^[αεηιουω]$/u;
const accent = /[\u0300\u0301\u0342]/gu;

function plain(text) {
  return text.normalize('NFD').replace(/\p{M}/gu, '');
}

function key(text) {
  return plain(text).toLowerCase().replace(/σ$/u, 'ς');
}

function attested(forms, target, why) {
  for (const form of forms.split(' ')) lesson.set(key(form), {form, target, why});
}

attested('ἀσφοδελός δειελός ὀβελός μυελός Σικελός στροβελός', ultima,
  'The form in the passage has a final acute.');
attested('κεφελός', ultima, 'Printed with a final acute. The edition marks this reading as uncertain.');
attested('ἀείδελος εἴκελος εὐτράπελος πέμπελος δέελος', antepenult,
  'The form in the passage has an antepenultimate acute.');
attested('ζάφελος', antepenult, 'Herodian explains ζάφελος as a compound from ζα- and ὀφέλλω.');
attested('εὔκηλος τράχηλος κάπηλος κάμηλος φάσηλος Στύμφηλος βέβηλος κίβδηλος ἐρύγηλος Πάμηλος Εὔζηλος',
  antepenult, 'The form in the passage has an antepenultimate acute.');
attested('ἐρύγμηλος', antepenult,
  'Herodian objects to Tyrannion’s final acute and gives the form with an antepenultimate acute.');

function format(text) {
  if (orthography.value === 'mono') {
    return text.normalize('NFD').replace(/\p{M}/gu, mark => (
      mark === '\u0308' ? mark : /[\u0300\u0301\u0342]/u.test(mark) ? '\u0301' : ''
    )).normalize('NFC');
  }
  return text.normalize('NFC');
}

function syllables(word) {
  const letters = word.normalize('NFD').match(/[^\p{M}]\p{M}*/gu) || [];
  const nuclei = [];
  for (let i = 0; i < letters.length; i++) {
    const first = letters[i];
    const next = letters[i + 1];
    const base = first[0].toLowerCase();
    if (!vowel.test(base)) continue;
    if (next && first.length === 1 && !next.includes('\u0308') &&
        diphthongs.has(base + next[0].toLowerCase())) i++;
    nuclei.push(i);
  }
  return {letters, nuclei};
}

function acuteOn({letters, nuclei}, fromEnd) {
  const index = nuclei.at(-fromEnd);
  return letters.map((letter, i) => letter.replace(accent, '') + (i === index ? '\u0301' : '')).join('');
}

function suggest(phrase) {
  const text = phrase.trim();
  const result = {norm: text || '—', ending: '—', target: '—', out: '—',
    why: 'Type a word ending in -ελος or -ηλος.'};
  const token = text.match(/([\p{Script=Greek}\p{M}]+)([.,;·!?;·…»”)\]]*)$/u);
  if (!token || !/^\p{Script=Greek}/u.test(token[1])) {
    if (text) result.why = 'Enter a Greek word at the end of the input.';
    return result;
  }

  const prefix = text.slice(0, token.index);
  if (prefix && /[\p{L}\p{N}]$/u.test(prefix)) {
    result.why = 'Enter a Greek word at the end of the input.';
    return result;
  }
  const punctuation = token[2];
  const word = token[1].replace(/σ$/u, 'ς');
  const lower = key(word);
  const ending = ['ηλος', 'ελος'].find(suffix => lower.endsWith(suffix));
  const show = resultWord => prefix + format(resultWord) + punctuation;
  result.norm = prefix + plain(word) + punctuation;
  if (ending) result.ending = '-' + ending;

  if (mode.value === 'none') {
    result.target = 'no accents';
    result.out = show(word.normalize('NFD').replace(accent, ''));
    result.why = 'Removed the accent from the last word.';
    return result;
  }

  const source = lesson.get(lower);
  if (mode.value === 'auto' && source) {
    const capitalized = /^\p{Lu}/u.test(word);
    const form = capitalized ? source.form[0].toUpperCase() + source.form.slice(1) : source.form;
    result.target = source.target;
    result.out = show(form);
    result.why = source.why;
    return result;
  }

  const scanned = syllables(word);
  const forced = mode.value !== 'auto';
  const fromEnd = mode.value === 'oxytone' ? 1 : 3;
  if (!forced && !ending) {
    result.out = show(word);
    result.why = 'No automatic suggestion for this ending.';
  } else if (scanned.nuclei.length < fromEnd) {
    result.out = show(word);
    result.why = fromEnd === 3 ? 'Fewer than three vowel groups. No antepenult to accent.' : 'No Greek vowel to accent.';
  } else {
    result.target = fromEnd === 3 ? antepenult : ultima;
    result.out = show(acuteOn(scanned, fromEnd));
    result.why = forced ? 'Manual accent placement.' :
      'Tentative suggestion. This word is outside the examples and the toy cannot check vowel quantity or morphology.';
  }
  return result;
}

function render() {
  const result = suggest(input.value);
  for (const [key, field] of Object.entries(fields)) field.textContent = result[key];
}

document.querySelector('#go').addEventListener('click', render);
input.addEventListener('keydown', event => {
  if (event.key === 'Enter' && !event.isComposing) render();
});
mode.addEventListener('change', render);
orthography.addEventListener('change', render);
document.querySelector('#rand').addEventListener('click', () => {
  const examples = Array.from(lesson.values());
  input.value = examples[Math.floor(Math.random() * examples.length)].form;
  render();
});
document.querySelector('#clear').addEventListener('click', () => {
  input.value = '';
  render();
  input.focus();
});
for (const button of document.querySelectorAll('button.chip')) {
  button.addEventListener('click', () => {
    input.value = button.dataset.w;
    render();
  });
}
render();

